if(!String(url).includes("/rpc/"))return _fetch(url,o);const fn=url.split("/rpc/")[1],b=JSON.parse(o.body||"{}");const R=id=>db.res.find(r=>r.id==id);
 const MVD={cafe:[36,0,6,5,2],restaurant:[2,9,6,5,3],cinema:[36,9,8,5,4],gym:[38,17,6,4,2],arena:[50,0,7,6,3]};
 const mvSettle=t=>{if(!t.mv||t.mv.at*1e3>Date.now())return;const k=t.mv.k,d=MVD[k],nd=[t.mv.to[0]+d[4],t.mv.to[1]+d[3]];t.layout=Object.assign({},t.layout,{[k]:t.mv.to});db.res.forEach(r=>{if(r.town_id==t.id&&r.place==k){r.x=nd[0];r.y=nd[1]}});t.mv=null;save()};
