 const hmDo=(t,r,site)=>{t.layout=Object.assign({},t.layout);t.layout.h=Object.assign({},t.layout.h);if(site==r.slot)delete t.layout.h[r.id];else t.layout.h[r.id]=site;if(!Object.keys(t.layout.h).length)delete t.layout.h;const d=door(site);db.res.forEach(x=>{if(x.town_id==t.id&&x.place=="home:"+r.id){x.x=d[0]+(x.id==r.id?0:1);x.y=d[1]}})};
